export const RAW_SENTENCES: StaticSentence[] = [
  { sentence: "Since we were regulated by law last month, we are now able to hugely enhance our efforts.", translation: "O'tgan oyda qonun bilan tartibga solinganimizdan beri, endi sa'y-harakatlarimizni ancha kuchaytira olamiz.", structure_note: "'Since' + Past Simple passiv orqali sabab bildiruvchi ergash gap; asosiy gapda natija ifodalangan.", difficulty: "B2", source: "L1" },
  { sentence: "Even though they are categorised as birds, African penguins aren't able to fly because of their heavy bones.", translation: "Ular qushlar toifasiga kiritilgan bo'lsa-da, Afrika pingvinlari og'ir suyaklari tufayli ucha olmaydi.", structure_note: "'Even though' bilan qat'iy qarama-qarshilik (concession) + 'because of' bilan sabab bildiruvchi ot birikmasi.", difficulty: "B2", source: "L1" },
  { sentence: "The more genetic diversity there is within a species, the higher the likelihood that at least some of the individuals will adapt and survive.", translation: "Bir tur ichida genetik xilma-xillik qanchalik ko'p bo'lsa, hech bo'lmaganda ba'zi individlarning moslashib omon qolish ehtimoli shunchalik yuqori bo'ladi.", structure_note: "'The more..., the higher...' — qiyosiy korrelyativ struktura (double comparative).", difficulty: "C1", source: "L1" },
  { sentence: "Having been responsible for the invention of numerous technologies since it was founded by Dwayne Roberts in 1957, Roberts has a philosophy of pioneering and innovation.", translation: "1957-yilda Dueyn Roberts tomonidan asos solinganidan beri ko'plab texnologiyalar ixtirosi uchun mas'ul bo'lgani sababli, Roberts kompaniyasi kashfiyotchilik va innovatsiya falsafasiga ega.", structure_note: "Perfect participle clause ('Having been responsible...') gap boshida sabab/fon ma'nosini bildiradi.", difficulty: "C1", source: "L1" },
  { sentence: "As kangaroos are such calm animals, Frisbee isn't disturbed by the noises and shouting of visitors at the zoo, which has helped him to settle in at his new home very quickly.", translation: "Kenguru shunchalik xotirjam hayvon bo'lgani uchun, Frisbi zooparkka kelgan tashrifchilarning shovqin-suronidan bezovta bo'lmaydi, bu esa unga yangi uyiga juda tez o'rganishiga yordam berdi.", structure_note: "'As' bilan sabab ergash gap + oxirida 'which' bilan butun gapga izoh beruvchi nonrestrictive relative clause.", difficulty: "C1", source: "L1" },
  { sentence: "Being a type of small to medium sized penguin species, African penguins average about 60 centimetres tall and weigh up to 3.6 kilograms.", translation: "Kichik-o'rta hajmdagi pingvin turi bo'lgani uchun, Afrika pingvinlari o'rtacha 60 santimetr bo'yga ega bo'lib, 3,6 kilogrammgacha vaznga ega bo'ladi.", structure_note: "'Being...' bilan boshlanuvchi present participle clause sabab/xususiyatni bildiradi.", difficulty: "B2", source: "L1" },
  { sentence: "They are struggling for nesting space due to human disruption and competing for food due to overfishing and pollution.", translation: "Ular inson faoliyati tufayli uya qurish joyi uchun, ovlash va ifloslanish tufayli esa oziq-ovqat uchun kurashmoqda.", structure_note: "Ikki marta takrorlangan 'due to' bilan parallel sabab konstruksiyasi.", difficulty: "B2", source: "L1" },
  { sentence: "It is where the students post academic problems that they come across and get support from the faculty members.", translation: "Bu talabalar duch kelgan akademik muammolarni joylashtiradigan va professor-o'qituvchilardan yordam oladigan joydir.", structure_note: "'It is where...' konstruksiyasi ichida 'that' bilan ikkinchi darajali relative clause joylashgan (nested relative clauses).", difficulty: "C1", source: "L2" },

  { sentence: "Although there are contrasting views as to why resin is produced, it is a plant's protection mechanism.", translation: "Qatronning nima uchun ishlab chiqarilishi haqida turli qarashlar mavjud bo'lsa-da, bu o'simlikning himoya mexanizmidir.", structure_note: "'Although' bilan qarama-qarshilik + 'as to why' bilan bilvosita savol (indirect question) ifodalangan ot birikmasi.", difficulty: "C1", source: "L3" },
  { sentence: "A piece with a visible and well-arranged insect is generally valued much higher than simple, solid amber.", translation: "Ichida yaxshi ko'rinadigan va tartibli joylashgan hasharot bo'lgan bo'lak odatda oddiy, yaxlit ambradan ancha yuqori baholanadi.", structure_note: "'much higher than' bilan kuchaytirilgan qiyoslash (comparative with intensifier).", difficulty: "B2", source: "L3" },
  { sentence: "If you really want to get your hands dirty, so to speak, I would recommend instead seeking a summer internship.", translation: "Agar haqiqatan ham, aytmoqchi, qo'l botirib ishlashni istasangiz, o'rniga yozgi amaliyot izlashni tavsiya qilardim.", structure_note: "Conditional Type 1 + 'would recommend' bilan maslahat, ichiga 'so to speak' idiomatik kirish so'zi qo'shilgan.", difficulty: "B2", source: "L3" },
  { sentence: "Despite there being other hospitals that are larger with more facilities than ours, we still have higher patient numbers.", translation: "Bizning kasalxonamizdan kattaroq va ko'proq imkoniyatlarga ega boshqa kasalxonalar mavjud bo'lishiga qaramay, bizda hali ham bemorlar soni ko'proq.", structure_note: "'Despite there being...' — 'despite' dan keyin gerund construction bilan qarama-qarshilik ifodalangan.", difficulty: "C1", source: "L4" },
  { sentence: "It seemed that patients were not concerned with the clarity of signs and notices in the hospital, as this option got the smallest number of votes.", translation: "Bemorlar kasalxonadagi belgi va e'lonlarning aniqligi bilan qiziqmaganga o'xshaydi, chunki bu variant eng kam ovoz oldi.", structure_note: "'It seemed that...' bilan taxmin ifodalovchi bosh gap + 'as' bilan sabab ergash gap.", difficulty: "B2", source: "L4" },
  { sentence: "The data showed that even though our hospital is not as centrally located as others, we offer a very good transportation service that enables patients to travel here by bus or train free of charge.", translation: "Ma'lumotlar shuni ko'rsatdiki, kasalxonamiz boshqalarga qaraganda markazda joylashmagan bo'lsa-da, biz bemorlarga avtobus yoki poyezdda bepul sayohat qilish imkonini beruvchi juda yaxshi transport xizmatini taklif etamiz.", structure_note: "Bir necha ergash gap qatlamlari: 'that' (izohlovchi) + 'even though' (qarama-qarshilik) + 'that' (relative clause).", difficulty: "C1", source: "L4" },
  { sentence: "We feel that some incentive is needed to boost motivation to perform better, and so we are implementing a system whereby staff will be awarded an extra bonus for their success.", translation: "Bizningcha, yaxshiroq ishlash uchun rag'batni oshirish uchun qandaydir undov omili kerak, shuning uchun xodimlar o'z muvaffaqiyati uchun qo'shimcha bonus oladigan tizimni joriy qilmoqdamiz.", structure_note: "'Whereby' — rasmiy uslubda 'by which/orqali' ma'nosini bildiruvchi relative adverb.", difficulty: "C1", source: "L4" },
  { sentence: "If you worked as a waiter in a hotel restaurant, you're bound to have worked with other waiters as part of a team.", translation: "Agar mehmonxona restoranida ofitsiant bo'lib ishlagan bo'lsangiz, albatta jamoa tarkibida boshqa ofitsiantlar bilan ishlagan bo'lishingiz kerak.", structure_note: "Conditional (Type 1) + 'bound to have + V3' — modal perfect construction bilan qat'iy ishonchni bildirish.", difficulty: "C1", source: "L5" },
  { sentence: "You might not think so, but if you write that you were offered the position of team leader, it shows a lot more about your character.", translation: "Balki shunday deb o'ylamassiz, lekin agar jamoa rahbari lavozimi taklif qilinganini yozsangiz, bu sizning xarakteringiz haqida ko'proq narsani ko'rsatadi.", structure_note: "'You might not think so, but...' — modal 'might' bilan taxmin, so'ngra 'if' shart ergash gap ichida 'that' noun clause joylashgan.", difficulty: "B2", source: "L5" },
  { sentence: "For 200 years, up to the time we are concerned with, potters had been making butter pots and pitchers and patterned plates, using the clay which was plentiful in the area where they lived.", translation: "200 yil davomida, biz gaplashayotgan davrgacha, kulollar sopol ustalari yashagan hududda mo'l bo'lgan loydan foydalanib, sariyog' idishlari, ko'zalar va naqshli likopchalar yasab kelishgan.", structure_note: "Past Perfect Continuous ('had been making') uzoq davom etgan o'tmish jarayonini bildiradi + ichma-ich joylashgan ikki relative clause ('which was plentiful', 'where they lived').", difficulty: "C2", source: "L5" },

  { sentence: "But although some of these individuals may have brought back samples of tea to their native country, it was not the Portuguese who were the first to ship back tea as a commercial import.", translation: "Garchi bu odamlarning ba'zilari choy namunalarini o'z vatanlariga olib kelgan bo'lishi mumkin bo'lsa-da, choyni tijorat maqsadida birinchi bo'lib olib kelganlar portugallar emas edi.", structure_note: "'Although' bilan concession + 'it was...who' cleft sentence konstruksiyasi urg'u berish uchun ishlatilgan.", difficulty: "C1", source: "R1" },
  { sentence: "So instead of trying to pack everyone back off to bed, Romford is trying to reclaim the town centre for a broader mix of people, and so to fulfil the original ambitions of the 24-hour-city dreamers.", translation: "Shunday qilib, hammani yotishga majburlashga urinish o'rniga, Romford shahar markazini kengroq turdagi odamlar uchun qaytarib olishga va shu tariqa 24 soatlik shahar orzu qiluvchilarning asl maqsadlarini amalga oshirishga harakat qilmoqda.", structure_note: "'Instead of + gerund' bilan qarama-qarshi harakat + 'so to + infinitive' natija/maqsadni bildiradi.", difficulty: "C1", source: "R1" },
  { sentence: "As the new licensing laws delegate the job of granting alcohol licences to local councils, cities across England will be trying to reclaim the night.", translation: "Yangi litsenziyalash qonunlari spirtli ichimliklar uchun litsenziya berish vazifasini mahalliy kengashlarga topshirgani sababli, butun Angliya bo'ylab shaharlar 'tunni qaytarib olish'ga harakat qilishadi.", structure_note: "'As' bilan sabab ergash gap + Future Continuous ('will be trying') asosiy gapda davom etayotgan kelajak harakatni bildiradi.", difficulty: "C1", source: "R1" },
  { sentence: "Just as important though is consumer awareness.", translation: "Shunga qaramay, iste'molchilarning xabardorligi xuddi shunday muhim ahamiyatga ega.", structure_note: "Inversion: urg'u berish uchun sifat old gapga chiqarilgan — normal tartib 'Consumer awareness is just as important' bo'lishi kerak edi.", difficulty: "C1", source: "R3" },
  { sentence: "Until the first elegant experiments by pioneers in the field such as Konrad Lorenz, naturalists wrote about animals as if they were slightly less intelligent humans.", translation: "Konrad Lorenz kabi soha kashfiyotchilarining birinchi nafis tajribalarigacha, tabiatshunoslar hayvonlar haqida xuddi ular biroz kam aqlli insonlardek yozishgan edi.", structure_note: "'As if' bilan noreal qiyoslash (unreal comparison, Past Simple bilan) + 'until' bilan vaqt chegarasi.", difficulty: "C2", source: "R6" },
  { sentence: "Even though the authorities intervened often to limit football as a public nuisance, there was a great deal of passion for the sport.", translation: "Hokimiyat futbolni jamoat tartibini buzuvchi omil sifatida cheklashga tez-tez aralashgan bo'lsa-da, bu sportga bo'lgan ishtiyoq juda katta edi.", structure_note: "'Even though' bilan kuchli qarama-qarshilik (concession) bildiruvchi ergash gap.", difficulty: "B2", source: "R6" },
  { sentence: "In some schools, particularly Rugby schools, the ball may be carried or touched with the hands, and opponents might be tripped and booted.", translation: "Ba'zi maktablarda, xususan Rugby maktablarida, to'pni qo'l bilan tutish yoki ko'tarish mumkin edi, raqiblarni esa yiqitish va tepish mumkin edi.", structure_note: "Modal passive voice ('may be carried', 'might be tripped') — imkoniyat/ruxsatni passiv shaklda ifodalash.", difficulty: "C1", source: "R6" },
  { sentence: "The end of the East India Company's monopoly on trade with China also had another result, which was more dramatic though less important in the long term: it ushered in the era of the tea clippers.", translation: "Sharqiy Hindiston kompaniyasining Xitoy bilan savdo monopoliyasining tugashi yana bir natijaga olib keldi, bu natija uzoq muddatda kamroq muhim bo'lsa-da, ko'proq dramatik edi: bu choy klipperlari davrini boshlab berdi.", structure_note: "Nonrestrictive relative clause ('which was...') ichida 'though' bilan qisqartirilgan concession joylashgan.", difficulty: "C2", source: "R1" },

  { sentence: "It has long been held that decisions made collectively by large groups of people are more likely to turn out to be accurate than decisions made by individuals.", translation: "Ko'pdan beri shunday fikr mavjud ediki, katta guruh odamlar tomonidan birgalikda qabul qilingan qarorlar yakka tartibda qabul qilingan qarorlarga qaraganda to'g'ri chiqish ehtimoli ko'proq.", structure_note: "'It has long been held that...' — passiv konstruksiya orqali umumiy qabul qilingan fikrni bildirish, ichida qiyoslash (comparative) mavjud.", difficulty: "C1", source: "R9" },
  { sentence: "By manipulating the robots, which were in the minority, Halloy was able to persuade the living cockroaches to choose an inappropriate shelter, even one which they had rejected before being infiltrated by the robots.", translation: "Ozchilikni tashkil etgan robotlarni boshqarish orqali, Halloy tirik tarakonlarni ilgari robotlar aralashmasdan turib rad etgan noto'g'ri boshpanani tanlashga ko'ndira oldi.", structure_note: "'By + gerund' bilan usul bildiruvchi ergash gap + ikkita ichma-ich joylashgan relative clause ('which were...', 'which they had rejected').", difficulty: "C2", source: "R9" },
  { sentence: "Although paper used for writing became popular by the 3rd century AD, it continued to be used for wrapping and other purposes.", translation: "Yozish uchun ishlatiladigan qog'oz miloddan keyingi 3-asrga kelib mashhur bo'lgan bo'lsa-da, u o'rash va boshqa maqsadlarda ishlatilishda davom etdi.", structure_note: "'Although' bilan qarama-qarshilik bildiruvchi ergash gap + passiv ('paper used for writing').", difficulty: "B2", source: "R10" },
  { sentence: "Finally, when the Moors from North Africa invaded Spain and Portugal they brought the technology with them, and so it was that papermaking entered Europe in the 12th century.", translation: "Nihoyat, Shimoliy Afrikadan kelgan mavrlar Ispaniya va Portugaliyaga bostirib kirganlarida, ular bu texnologiyani o'zlari bilan olib keldilar va shu tariqa qog'oz ishlab chiqarish 12-asrda Yevropaga kirib keldi.", structure_note: "'So it was that...' — natijani urg'u bilan ifodalovchi emfatik konstruksiya.", difficulty: "C1", source: "R10" },
  { sentence: "There is no reason why state housing should look cheap in my view.", translation: "Menimcha, davlat uy-joyi arzon ko'rinishi kerakligi uchun hech qanday sabab yo'q.", structure_note: "'There is no reason why...should' — fikr-mulohaza bildiruvchi modal konstruksiya.", difficulty: "B2", source: "R10" },
  { sentence: "By doing this, the development avoids the uniform appearance of so many state housing projects, which residents complain denies them any sense of individual identity.", translation: "Shuning natijasida, bu loyiha ko'plab davlat uy-joyi loyihalariga xos bo'lgan bir xillikdan qochadi, aholi buning ularni individual o'ziga xoslik hissidan mahrum qilishidan shikoyat qiladi.", structure_note: "'By doing this' usul bildiruvchi gerund clause + nonrestrictive relative clause ('which residents complain...') ichida yana bir ergash gap yashiringan.", difficulty: "C2", source: "R10" },
  { sentence: "We acknowledge that if you are going to ask people to live in these quite tightly-packed communities, you have to actually help them to get to know each other by organising morning teas and street barbecues.", translation: "Biz shuni tan olamizki, agar odamlardan shunchalik zich joylashgan jamoalarda yashashni so'rasangiz, ularni bir-biri bilan tanishtirish uchun ertalabki choy va ko'cha barbekyularini uyushtirish orqali yordam berishingiz kerak.", structure_note: "'That' noun clause ichida 'if' shart ergash gap joylashgan (nested conditional inside a noun clause).", difficulty: "C1", source: "R10" },
  { sentence: "Underneath the tree lay an unknown black substance which we now know as graphite.", translation: "Daraxt tagida biz hozir grafit deb bilgan noma'lum qora modda yotardi.", structure_note: "O'rin bildiruvchi ravish old gapga chiqarilgan inversion ('Underneath the tree lay...') + relative clause ('which we now know as').", difficulty: "C1", source: "R11" },

  { sentence: "There is thus a nice if ironic, symmetry in the idea that a similar impact brought about the dinosaurs' rise.", translation: "Shunday qilib, xuddi shunga o'xshash zarba dinozavrlarning yuksalishiga olib kelgan degan g'oyada chiroyli, ammo istehzoli bir simmetriya mavjud.", structure_note: "'Nice if ironic' — 'if' so'zi bu yerda 'though' ma'nosida qisqartirilgan concessive insert sifatida ishlatilgan.", difficulty: "C2", source: "R12" },
  { sentence: "They were all made obsolete by a radically different machine, which had been developed by an obscure photographic-supply company.", translation: "Ularning barchasi kam tanilgan fotografik-ta'minot kompaniyasi tomonidan ishlab chiqilgan tubdan farqli mashina tufayli eskirib qoldi.", structure_note: "Passive voice ('were made obsolete', 'had been developed') + relative clause bilan sabab ko'rsatilgan.", difficulty: "C1", source: "R14" },
  { sentence: "All of them turned him down, expressing what he later called 'an enthusiastic lack of interest' and thereby passing up the opportunity to manufacture what Fortune magazine would describe as 'the most successful product ever marketed in America.'", translation: "Ularning barchasi uni rad etdi, keyinchalik u buni 'ishtiyoqli qiziqishsizlik' deb atagan narsani namoyon qilib, va shu tariqa Fortune jurnali 'Amerikada sotilgan eng muvaffaqiyatli mahsulot' deb ta'riflaydigan imkoniyatni qo'ldan boy berdi.", structure_note: "Ketma-ket kelgan participle clauselar ('expressing...', 'passing up...') + ikki marta ichma-ich joylashgan 'what' nominal (free relative) gaplar.", difficulty: "C2", source: "R14" },
  { sentence: "It's like doctors trying to treat humans by only looking at their feet.", translation: "Bu xuddi shifokorlar odamlarni faqat oyoqlariga qarab davolashga urinishiga o'xshaydi.", structure_note: "'It's like...' bilan o'xshatish (simile) + 'by + gerund' usul bildiruvchi ergash gap.", difficulty: "B2", source: "R14" },
  { sentence: "Given these factors, it comes as no surprise that operations involving these balloons numbered just six between 1986 and 2001.", translation: "Bu omillarni hisobga olgan holda, 1986 va 2001 yillar orasida bu balonlar bilan bog'liq operatsiyalar atigi olti marta bo'lganligi hech kimni hayron qoldirmaydi.", structure_note: "'Given' bilan boshlanuvchi sabab bildiruvchi qisqartirilgan gap + 'it comes as no surprise that' emfatik konstruksiya.", difficulty: "C1", source: "R14" },
  { sentence: "This may be one reason why, according to a broad range of studies in people over 60, the better educated a person is, the more likely they are to perform better in life and on psychological tests.", translation: "60 yoshdan oshgan odamlar bo'yicha keng ko'lamli tadqiqotlarga ko'ra, bu, ehtimol, inson qanchalik yaxshi ta'lim olgan bo'lsa, u hayotda va psixologik testlarda shunchalik yaxshi natija ko'rsatishi mumkinligining sabablaridan biridir.", structure_note: "'The more...the more' qiyosiy korrelyativ struktura 'why' ergash gapi ichiga joylashtirilgan, orasiga qo'shimcha ergash gap ('according to...') kiritilgan.", difficulty: "C2", source: "R13" },

  { sentence: "Far from encouraging illegality, these gurus argue that, in the same way big corporations sometimes emulate start-ups, business leaders could learn from the underworld about flexibility, innovation and the ability to pivot quickly.", translation: "Bu mutaxassislar qonunbuzarlikni rag'batlantirishdan yiroq bo'lib, xuddi katta korporatsiyalar ba'zan startaplarga taqlid qilgani kabi, biznes rahbarlari jinoiy dunyodan moslashuvchanlik, innovatsiya va tezkor o'zgarish qobiliyati haqida o'rganishlari mumkinligini ta'kidlaydilar.", structure_note: "'Far from + gerund' bilan boshlanuvchi qarama-qarshilikni bildiruvchi old gap + parentetik qiyoslash ('in the same way...') gap ichiga kiritilgan.", difficulty: "C2", source: "R19" },
  { sentence: "One person who took part in a study into aphantasia said he had started to feel 'isolated' and 'alone' after discovering that other people could see images in their heads.", translation: "Afantaziya bo'yicha tadqiqotda qatnashgan bir kishi, boshqa odamlar o'z boshida tasvirlarni ko'ra olishini bilib olganidan keyin o'zini 'yakkalangan' va 'yolg'iz' his qila boshlaganini aytdi.", structure_note: "'Who' relative clause + Past Perfect ('had started') + ichiga joylashtirilgan 'that' noun clause.", difficulty: "C1", source: "R19" },
  { sentence: "Being unable to reminisce about his mother years after her death led to him being 'extremely distraught'.", translation: "Onasining o'limidan yillar o'tib ham uni eslay olmaslik uni 'juda qattiq g'amgin' holatga olib keldi.", structure_note: "Gap egasi vazifasida gerund ('Being unable...') + 'led to' dan keyin ham gerund ('being extremely distraught') ishlatilgan.", difficulty: "C1", source: "R19" },
  { sentence: "While traditional businesses focus on rules they have to follow, criminals look to circumvent them.", translation: "An'anaviy bizneslar amal qilishlari kerak bo'lgan qoidalarga e'tibor qaratsalar, jinoyatchilar esa ularni chetlab o'tishga harakat qiladilar.", structure_note: "'While' bilan qarama-qarshilik + 'rules they have to follow' — nol relative clause (that/which tushirilgan).", difficulty: "B2", source: "R19" },

  { sentence: "Taste is now recognised as being a far more complex and important area of neurological science than was previously believed by most people.", translation: "Ta'm hissi hozirda ko'pchilik ilgari o'ylagandan ancha murakkab va muhim neyrologiya sohasi sifatida tan olinmoqda.", structure_note: "Passiv ovoz ('is recognised') + qiyosiy daraja ('more...than was previously believed') qo'shimcha passiv bilan.", difficulty: "C1", source: "L7" },
  { sentence: "The brain picks up cues from the way the product is presented, as well as the product itself, which trigger taste sensations.", translation: "Miya mahsulotning o'zidan tashqari, u qanday taqdim etilishidan ham signal oladi, bu esa ta'm sezgilarini uyg'otadi.", structure_note: "'As well as' bilan qo'shimcha ma'lumot + oxirida butun gapga izoh beruvchi nonrestrictive 'which' clause.", difficulty: "C1", source: "L7" },
  { sentence: "No matter how short you make that resume, though, you do not want to forget to tell HR how to contact your references.", translation: "Rezyumeni qanchalik qisqa qilsangiz ham, HR bo'limiga murojaatchilaringiz bilan qanday bog'lanishni aytishni unutmasligingiz kerak.", structure_note: "'No matter how' bilan konsessiv ergash gap + 'forget to' dan keyin infinitiv.", difficulty: "B2", source: "L7" },

  { sentence: "While its appearance is the obvious attribute at which to marvel, there is far more to this building than meets the eye.", translation: "Uning ko'rinishi hayratlanarli xususiyat bo'lsa-da, bu binoda ko'zga tashlanganidan ancha ko'p narsa bor.", structure_note: "'At which to marvel' — preposition + relative pronoun + infinitiv konstruksiya; 'than meets the eye' idiomatik ibora.", difficulty: "C1", source: "L10" },
  { sentence: "Given London's notoriously bad weather, the architects knew they must devise a quality temperature regulation system.", translation: "London ob-havosining yomon ma'noda mashhurligini hisobga olgan holda, me'morlar sifatli harorat tartibga solish tizimini ishlab chiqishlari kerakligini bilishardi.", structure_note: "'Given' + ot birikma bilan boshlanuvchi sabab/fon bildiruvchi participle construction.", difficulty: "C1", source: "L10" },
  { sentence: "A special system designed to reduce the building's reliance on air conditioning was devised that cuts consumption in half compared to standard office buildings.", translation: "Binoning konditsionerlarga bog'liqligini kamaytirish uchun mo'ljallangan alohida tizim ishlab chiqilgan bo'lib, u standart idora binolariga solishtirganda energiya sarfini ikki hissa kamaytiradi.", structure_note: "Ikki qatlamli passiv qurilma ('was devised that cuts') + 'designed to' infinitiv maqsad bildiruvchi.", difficulty: "C1", source: "L10" },

  { sentence: "These games may be regarded as the ancestors of modern codes of football, and by comparison with later models of football, they were chaotic and had little cooperation.", translation: "Bu o'yinlar zamonaviy futbol qoidalarining ajdodlari sifatida qaralishi mumkin, va keyingi futbol modellari bilan solishtirganda, ular tartibsiz bo'lib, hamkorlik deyarli bo'lmagan.", structure_note: "Passiv modal ('may be regarded as') + 'by comparison with' bilan qiyoslash old birikmasi.", difficulty: "C1", source: "L11" },
  { sentence: "As mob football died away, there grew a greater concern for players' health, with many clubs affording their top players access to frequent medical check-ups.", translation: "Ommaviy futbol yo'qolib borishi bilan, o'yinchilar salomatligiga ko'proq e'tibor kuchaydi, ko'plab klublar esa eng yaxshi o'yinchilariga muntazam tibbiy ko'rikdan o'tish imkonini berdi.", structure_note: "'As' bilan vaqt/sabab ergash gap + oxirida 'with' absolute construction (with + noun + gerund).", difficulty: "C2", source: "L11" },
  { sentence: "Although much of this research has taken place through observation of captive chimps, the results are widely seen as an authoritative reflection of chimps living in the wild.", translation: "Bu tadqiqotlarning ko'pi asirlikdagi shimpanzelarni kuzatish orqali olib borilgan bo'lsa-da, natijalar tabiatda yashaydigan shimpanzelarning ishonchli aksi sifatida qaraladi.", structure_note: "'Although' bilan konsessiv ergash gap (Present Perfect) + asosiy gapda passiv ovoz.", difficulty: "C1", source: "L14" },
  { sentence: "It is not unheard of for dominant females within a community to unite and overthrow the alpha male, backing another in his place.", translation: "Jamoa ichidagi hukmron urg'ochilarning birlashib, alfa erkakni ag'darib, uning o'rniga boshqasini qo'yishlari kamdan-kam uchraydigan hol emas.", structure_note: "'It is not unheard of for X to do Y' — formal emfatik konstruksiya + oxirida present participle clause ('backing...').", difficulty: "C2", source: "L14" },

  { sentence: "Though some things about putting together a room are subjective and based on one's individual taste, materials appropriate to a room's function are much more straightforward.", translation: "Xonani jihozlashga oid ba'zi narsalar sub'ektiv va shaxsiy did asosida bo'lsa-da, xonaning vazifasiga mos materiallarni tanlash ancha soddaroqdir.", structure_note: "'Though' bilan konsessiv ergash gap + gap egasidan keyin qisqartirilgan relative clause ('materials appropriate to...').", difficulty: "C1", source: "L18" },
  { sentence: "Since form and material follow function, one should only use the more reflective materials in rooms where the cultivation and expression of energy is important.", translation: "Shakl va material vazifaga bog'liq bo'lgani uchun, energiya ifodasi muhim bo'lgan xonalarda faqat ko'proq nur qaytaradigan materiallardan foydalanish kerak.", structure_note: "'Since' bilan sabab ergash gap + 'where' bilan joy bildiruvchi relative clause.", difficulty: "C1", source: "L18" },
  { sentence: "Although they understand the potentially negative consequences of their actions, present-orientated children persist with the behaviour because they're not living for the future.", translation: "Bugungi kunga yo'naltirilgan bolalar o'z harakatlarining salbiy oqibatlarini tushunsalar ham, kelajak uchun yashamagani sababli shu xatti-harakatni davom ettiradilar.", structure_note: "'Although' konsessiv ergash gap + 'because' sabab ergash gapi bitta gapda birlashtirilgan.", difficulty: "C1", source: "L19" },
  { sentence: "Seeing these conflicts as differences in time perspective, rather than distinctions of character, can facilitate more effective cooperation between people.", translation: "Bu ziddiyatlarni xarakter farqi emas, balki vaqtga munosabat farqi sifatida ko'rish, odamlar orasida samaraliroq hamkorlikka yordam beradi.", structure_note: "Gerund gap egasi ('Seeing...') + 'rather than' bilan qarama-qarshi qo'yish.", difficulty: "C2", source: "L19" },

  { sentence: "It is imperative that we protect these buildings, as they are valuable examples of our history and culture.", translation: "Bu binolarni asrab-avaylashimiz shart, chunki ular bizning tarix va madaniyatimizning qadrli namunalaridir.", structure_note: "'It is imperative that' emfatik konstruksiya + subjunktiv ma'nodagi asosiy fe'l + 'as' sabab ergash gapi.", difficulty: "C1", source: "L21" },
  { sentence: "Without sleep, an animal is much less capable of avoiding an attack — this is the case for all animals, whether they are reptiles, mammals or fish.", translation: "Uyqusiz hayvon hujumdan qochish qobiliyatini ancha yo'qotadi — bu sudralib yuruvchilar, sut emizuvchilar yoki baliqlar bo'lishidan qat'i nazar, barcha hayvonlar uchun to'g'ri.", structure_note: "'Without' bilan boshlanuvchi shartli old birikma + 'whether...or' bilan muqobil holatlar sanab o'tilgan.", difficulty: "C1", source: "L23" },
  { sentence: "Should those GM fish ever escape into the sea, these fish might cannibalize others or outcompete wild-type fish for food.", translation: "Agar bu genetik o'zgartirilgan baliqlar dengizga qochib chiqsa, ular boshqalarni yeb qo'yishi yoki yovvoyi baliqlar bilan oziq-ovqat uchun raqobatda ustun kelishi mumkin.", structure_note: "'Should' bilan inversiya orqali shartli gap (= 'If those GM fish should ever escape...').", difficulty: "C1", source: "L24" },

  { sentence: "For 200 years, up to the time we are concerned with, potters had been making butter pots and pitchers, using the clay which was plentiful in the area where they lived.", translation: "200 yil davomida, biz gaplashayotgan davrgacha, kulollar sariyog' idishlari va ko'zalar yasab kelgan, ular yashagan hududda ko'p bo'lgan loydan foydalanganlar.", structure_note: "Past Perfect Continuous ('had been making') + ikki bosqichli relative clause ('which was...', 'where they lived').", difficulty: "C1", source: "L31" },
  { sentence: "One factor that will consistently lead to a boring, forgettable speech is writing down your entire speech.", translation: "Zerikarli va yodda qolmaydigan nutqqa doimo olib keladigan omillardan biri butun nutqni qog'ozga yozib olishdir.", structure_note: "Gap egasi 'One factor that...' relative clause bilan kengaytirilgan, kesim vazifasida gerund ('writing down...').", difficulty: "B2", source: "L33" },
  { sentence: "The fact that rabbits increased so rapidly is perhaps more understandable when we remind ourselves that they had originally been introduced to England from continental Europe eight centuries earlier.", translation: "Quyonlarning bunchalik tez ko'payib ketishi, ularning sakkiz asr oldin qit'aviy Yevropadan Angliyaga olib kelinganini yodga olsak, ehtimol ancha tushunarli bo'ladi.", structure_note: "'The fact that...' nominal ergash gap + 'when' ergash gap ichida yana bir 'that' clause (Past Perfect Passive).", difficulty: "C2", source: "L34" },

  { sentence: "Lone trees separated from the surrounding forest are also susceptible to cyclones, which reach speeds of over 200 kph in the area, and can easily uproot even a 30-metre baobab.", translation: "O'rmondan ajratilgan yakka daraxtlar, hududda tezligi 200 km/soatdan oshadigan tsiklonlarga ham moyil bo'lib, ular 30 metrlik baobabni ham osongina qo'porib tashlashi mumkin.", structure_note: "Past participle ('separated...') sifatdosh vazifasida + 'which' nonrestrictive relative clause ikki fe'l bilan.", difficulty: "C1", source: "R5" },
  { sentence: "Had the Greek mining been on a larger scale, it could have caused problems similar to those faced by the Spanish centuries later.", translation: "Agar yunon konchiligi kattaroq miqyosda bo'lganida, u asrlar o'tib ispanlar duch kelgan muammolarga o'xshash muammolarni keltirib chiqarishi mumkin edi.", structure_note: "'Had' bilan inversiya orqali III tip shartli gap (= 'If the Greek mining had been...').", difficulty: "C2", source: "R5" },
  { sentence: "While stone takes about twice as long to grind into an axe compared to shell, the harder material keeps its sharp edge for longer.", translation: "Toshni boltaga aylantirish chig'anoqqa solishtirganda deyarli ikki hissa ko'proq vaqt olsa-da, qattiqroq material o'zining o'tkirligini uzoqroq saqlaydi.", structure_note: "'While' bilan qarama-qarshilik + qiyoslash konstruksiyasi ('twice as long...compared to').", difficulty: "C1", source: "R15" },
  { sentence: "When peatlands are drained for cultivation, they become net carbon emitters instead of active carbon stores.", translation: "Botqoqli torf yerlar ekin ekish uchun quritilganda, ular faol uglerod omboridan uglerod chiqaruvchiga aylanadi.", structure_note: "'When' vaqt ergash gap (passiv) + 'instead of' bilan qarama-qarshi qo'yish.", difficulty: "C1", source: "R15" },

  { sentence: "It's now widely recognised that, while largely ineffective in improving objective symptoms, placebos are genuinely effective in treating subjective, self-reported symptoms.", translation: "Hozirda placebolar ob'ektiv alomatlarni yaxshilashda ko'p jihatdan samarasiz bo'lsa-da, sub'ektiv, o'z-o'zidan bildirilgan alomatlarni davolashda haqiqatan samarali ekani keng tan olinadi.", structure_note: "'That' clause ichiga joylashgan 'while' konsessiv ergash gap (parentetik).", difficulty: "C2", source: "R16" },
  { sentence: "Smith's discovery that beds of rocks can be distinguished by the fossils found in them was a concept virtually unrecognised by geologists of that period.", translation: "Smitning tosh qatlamlarini ulardagi qazilma qoldiqlar orqali ajratish mumkinligi haqidagi kashfiyoti, o'z davri geologlari tomonidan deyarli tan olinmagan tushuncha edi.", structure_note: "Gap egasi ichida 'that' nominal clause + passiv sifatdosh ('unrecognised by...').", difficulty: "C1", source: "R17" },
  { sentence: "Cestius' actual tomb within the pyramid, and the inscription identifying it as his, weren't rediscovered until the 1660s, when the pyramid underwent restoration.", translation: "Piramida ichidagi Sestiyning haqiqiy maqbarasi va uni tasdiqlovchi yozuv faqat 1660-yillarda, piramida ta'mirlanayotganda qayta kashf etilgan.", structure_note: "'Not...until' konstruksiyasi + 'when' bilan vaqt bildiruvchi relative clause.", difficulty: "C1", source: "R18" },
  { sentence: "Such was the damage to the grasslands that even now few of the pastures have recovered.", translation: "O'tloqlarga yetkazilgan zarar shu qadar katta bo'lganki, hozirgacha ozgina yaylovlar tiklana olgan.", structure_note: "'Such...that' inversiya orqali natija bildiruvchi emfatik struktura.", difficulty: "C1", source: "R20" },

  { sentence: "E-training promises more effective teaching techniques by integrating audio, video, animation, text and interactive materials with the intent of teaching each student at his or her own pace.", translation: "E-o'qitish audio, video, animatsiya, matn va interaktiv materiallarni birlashtirib, har bir talabani o'z sur'atida o'qitish maqsadida samaraliroq usullarni taklif etadi.", structure_note: "'By + gerund' usul bildiruvchi ergash gap + 'with the intent of + gerund' maqsad bildiruvchi birikma.", difficulty: "C1", source: "R21" },
  { sentence: "The fantastic food-stream market is reminiscent of the global housing market, where homeownership has become the privilege of a few, who either cannot participate, or sign their lives away to banks.", translation: "Fantastik oziq-ovqat oqimi bozori global uy-joy bozoriga o'xshaydi, u yerda uyga egalik qilish ozchilikning imtiyoziga aylangan, qolganlar esa unda qatnasha olmaydi yoki banklarga umrbod qarzga botadi.", structure_note: "'Be reminiscent of' ibora + ikki qatlamli relative clause ('where...', 'who...').", difficulty: "C2", source: "R22" },
  { sentence: "Within a tenth of a second of seeing an unfamiliar face, we have already made a judgement about its owner's character.", translation: "Notanish yuzni ko'rgandan so'ng soniyaning o'ndan bir qismi ichida, biz uning egasining xarakteri haqida allaqachon xulosa chiqarib bo'lamiz.", structure_note: "Vaqt bildiruvchi old birikma ('within...of seeing') + Present Perfect.", difficulty: "B2", source: "R23" },
  { sentence: "A lifetime of scowling, grumpiness and grimaces seemed to have left its mark.", translation: "Umr davomida qovog'ini solib yurish, injiqlik va tirjayish o'z izini qoldirganga o'xshaydi.", structure_note: "'Seemed to have + V3' — Perfect Infinitive orqali o'tmishdagi natijaga ishora.", difficulty: "C1", source: "R23" },

  { sentence: "Well aware of the difficulties, educators have given a great deal of thought to how they can best help children learn to read.", translation: "Qiyinchiliklardan yaxshi xabardor bo'lgan pedagoglar, bolalarga o'qishni o'rgatishning eng yaxshi yo'lini qanday topish haqida ko'p o'ylab kelishmoqda.", structure_note: "Qisqartirilgan sifatdosh birikma ('Well aware of...') gap boshida + ichki 'how' savol gapi.", difficulty: "B2", source: "R24" },
  { sentence: "Without paper, this kind of collaborative and iterative work process would be much more difficult.", translation: "Qog'ozsiz, bu kabi hamkorlikdagi va takrorlanuvchi ish jarayoni ancha qiyinroq bo'lardi.", structure_note: "'Without' bilan shartli ma'no + 'would be' II tip shartli natija.", difficulty: "B2", source: "R25" },
  { sentence: "If such catastrophic temperature rises are to be avoided, the quantity of greenhouse gases being released into the atmosphere must be reduced.", translation: "Agar bunday halokatli harorat ko'tarilishining oldini olish kerak bo'lsa, atmosferaga chiqarilayotgan issiqxona gazlari miqdori kamaytirilishi shart.", structure_note: "'Be + to infinitive' majburiylik/rejalashtirilgan harakatni bildiradi + passiv 'must be reduced'.", difficulty: "C1", source: "R26" },
  { sentence: "Ships should be equipped to be seaworthy, aircraft should be equipped to be airworthy, but there is no legislation in place to ensure that a spacecraft is spaceworthy.", translation: "Kemalar dengizga chiqishga, samolyotlar uchishga layoqatli bo'lishi kerak, ammo kosmik kemaning parvozga layoqatli ekanligini ta'minlaydigan qonunchilik mavjud emas.", structure_note: "Uch qismli parallel struktura, oxirida 'but' bilan qarama-qarshilik.", difficulty: "C1", source: "R26" },

  { sentence: "So important is memory that the Charles A. Dana Foundation recently spent $8.4 million to set up a consortium of leading medical centres to measure memory loss and aging.", translation: "Xotira shu qadar muhimki, Charles A. Dana fondi so'nggi paytlarda xotira yo'qotilishi va qarishni o'lchash uchun yetakchi tibbiy markazlar konsorsiumini tashkil etishga 8,4 million dollar sarfladi.", structure_note: "'So + sifat + is + ega' inversiya orqali 'that' natija ergash gapini kuchaytirish.", difficulty: "C2", source: "R27" },
  { sentence: "Unless scientists and community leaders directed a worldwide effort to stabilize the decline of local languages, nine-tenths of the linguistic diversity of humankind would probably be doomed to extinction.", translation: "Agar olimlar va jamoat rahbarlari mahalliy tillarning yo'qolishini barqarorlashtirish uchun butun dunyo miqyosidagi harakatni boshqarmasa, insoniyatning til xilma-xilligining o'ndan to'qqiz qismi yo'qolishga mahkum bo'ladi.", structure_note: "'Unless' salbiy shartli ergash gap + 'would be doomed to' passiv konstruksiya.", difficulty: "C1", source: "R27" },
  { sentence: "Although physically Antarctica is no closer and probably no warmer, the continent and its surrounding ocean are increasingly seen to be an integral part of Planet Earth.", translation: "Fizik jihatdan Antarktida yaqinlashmagan va issiqroq bo'lmasa-da, bu qit'a va uni o'rab turgan okean tobora ko'proq Yer sayyorasining ajralmas qismi sifatida qaralmoqda.", structure_note: "'Although' konsessiv ergash gap + passiv 'are seen to be' konstruksiyasi.", difficulty: "C1", source: "R28" },
  { sentence: "Since only freshwater freezes into ice, the water that remains becomes increasingly salty and dense, sinking until it spills over the continental shelf.", translation: "Faqat chuchuk suv muzga aylangani sababli, qolgan suv tobora sho'r va zich bo'lib, materik shelfidan toshib chiquncha cho'kib boradi.", structure_note: "'Since' sabab ergash gap + oxirida present participle clause ('sinking until...').", difficulty: "C1", source: "R28" },

  { sentence: "Encouraged by his storm-warning success, FitzRoy then started a public weather forecasting service.", translation: "Bo'ron haqida ogohlantirish xizmatidagi muvaffaqiyatidan ruhlangan FitzRoy keyin ommaviy ob-havo bashorati xizmatini yo'lga qo'ydi.", structure_note: "Past participle clause ('Encouraged by...') gap boshida sabab bildiradi.", difficulty: "B2", source: "R31" },
  { sentence: "It is indisputable that FitzRoy was way ahead of his time, but it is only in recent years that he has been recognised as a towering figure in meteorology.", translation: "FitzRoy o'z davridan ancha oldinda bo'lgani shubhasiz, ammo u meteorologiyaning yetakchi siymosi sifatida faqat so'nggi yillarda tan olindi.", structure_note: "Ikki marta ishlatilgan 'it is...that' emfatik (cleft) konstruksiya.", difficulty: "C1", source: "R31" },
  { sentence: "While there is no argument that dingoes will prey on sheep if given the chance, they don't hunt cattle once the calves are much past two or three weeks old.", translation: "Dingolar imkoniyat topsa qo'ylarni ovlashiga shubha yo'q bo'lsa-da, buzoqlar ikki-uch haftalikdan katta bo'lgach ularni ovlamaydi.", structure_note: "'While' konsessiv ergash gap + 'once' vaqt ergash gapi (ikkinchi shart bilan).", difficulty: "C1", source: "R32" },
  { sentence: "Any business that pursues its ends at the expense of the society in which it operates will find its success to be illusory and ultimately temporary.", translation: "Faoliyat yuritayotgan jamiyat hisobidan o'z maqsadlariga erishadigan har qanday biznes, muvaffaqiyatining soxta va oxir-oqibat vaqtinchalik bo'lganini ko'radi.", structure_note: "Ikki qatlamli relative clause ('that pursues...', 'in which it operates') gap egasini kengaytiradi.", difficulty: "C1", source: "R35" },
];

export function buildGamePool(count: number): { items: GameMasterItem[]; sentences: GameMasterSentence[] } {
  const items: GameMasterItem[] = shuffle(RAW_ITEMS).slice(0, count).map((it, idx) => ({ ...it, id: `item-${idx}-${it.word}` }));
  const sentences: GameMasterSentence[] = shuffle(RAW_SENTENCES).slice(0, count).map((s, idx) => ({ ...s, id: `sent-${idx}` }));
  return { items, sentences };
}

export function getAllItems(): GameMasterItem[] {
  return RAW_ITEMS.map((it, idx) => ({ ...it, id: `item-${idx}-${it.word}` }));
}

export function getAllSentences(): GameMasterSentence[] {
  return RAW_SENTENCES.map((s, idx) => ({ ...s, id: `sent-${idx}` }));
}

function shuffle<T>(arr: T[]): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
